<?php
namespace Tests\Feature;use App\Models\Activity;use App\Models\ActivityType;use App\Models\Company;use App\Models\User;use Illuminate\Foundation\Testing\RefreshDatabase;use Laravel\Sanctum\Sanctum;use Tests\TestCase;class ActivityTest extends TestCase{    use RefreshDatabase;    protected function setUp(): void    {        parent::setUp();        $this->user = User::factory()->create();        Sanctum::actingAs($this->user, ['*']);        $this->activityType = ActivityType::create([            'name' => 'Tipo de Atividade Teste',            'slug' => 'tipo-atividade-teste',        ]);        $this->company = $this->createCompany([            'corporate_name' => 'Empresa Teste Ltda',            'trade_name' => 'Empresa Teste',            'tax_id' => '12345678000190',            'status' => 'prospecting',        ]);        $this->activityData = [            'activity_type_id' => $this->activityType->id,            'company_id' => $this->company->id,            'title' => 'Atividade de Teste',            'status' => 'pending',        ];    }    /**     * Teste: listar atividades com sucesso (index).     */    public function test_list_activities_success(): void    {        foreach (range(1, 3) as $i) {            $this->createActivity([                'activity_type_id' => $this->activityType->id,                'company_id' => $this->company->id,                'title' => "Atividade {$i}",                'status' => 'pending',            ]);        }        $response = $this->get('/api/v1/activities');        $response->assertStatus(200);        $response->assertJson([            'success' => true,            'status' => 200,        ]);        $response->assertJsonStructure([            'data' => [                'items',                'pagination',            ],            'message',            'status',        ]);    }    /**     * Teste: buscar atividade por ID com sucesso (show).     */    public function test_show_activity_success(): void    {        $activity = $this->createActivity([            'activity_type_id' => $this->activityType->id,            'company_id' => $this->company->id,            'title' => 'Atividade para Buscar',            'status' => 'pending',        ]);        $response = $this->get("/api/v1/activities/{$activity->id}");        $response->assertStatus(200);        $response->assertJson([            'success' => true,            'status' => 200,            'message' => 'Atividade encontrada.',        ]);        $response->assertJsonStructure([            'data' => [                'id',                'title',                'status',                'activity_type_id',                'company_id',            ],            'message',            'status',        ]);    }    /**     * Teste: buscar atividade inexistente retorna 404.     */    public function test_show_activity_not_found(): void    {        $response = $this->get('/api/v1/activities/99999');        $response->assertStatus(404);        $response->assertJson([            'success' => false,            'status' => 404,        ]);    }    /**     * Teste: criar atividade com sucesso (store).     */    public function test_store_activity_success(): void    {        $response = $this->post('/api/v1/activities', $this->activityData);        $response->assertStatus(201);        $response->assertJson([            'success' => true,            'status' => 201,            'message' => 'Atividade criada com sucesso.',        ]);        $response->assertJsonStructure([            'data' => [                'id',                'title',                'status',                'activity_type_id',                'company_id',            ],            'message',            'status',        ]);        $this->assertDatabaseHas('activities', [            'title' => 'Atividade de Teste',            'status' => 'pending',        ]);    }    /**     * Teste: criar atividade com dados inválidos retorna erro de validação.     */    public function test_store_activity_validation_error(): void    {        $invalidData = [            'activity_type_id' => null,            'company_id' => null,            'title' => '',            'status' => '',        ];        $response = $this->post('/api/v1/activities', $invalidData);        $response->assertStatus(422);        $response->assertJsonValidationErrors([            'activity_type_id',            'title',            'status',        ]);    }    /**     * Teste: atualizar atividade com sucesso (update).     */    public function test_update_activity_success(): void    {        $activity = $this->createActivity([            'activity_type_id' => $this->activityType->id,            'company_id' => $this->company->id,            'title' => 'Atividade Original',            'status' => 'pending',        ]);        $updateData = [            'title' => 'Atividade Atualizada',            'status' => 'completed',        ];        $response = $this->put("/api/v1/activities/{$activity->id}", $updateData);        $response->assertStatus(200);        $response->assertJson([            'success' => true,            'message' => 'Atividade atualizada com sucesso.',        ]);        $this->assertDatabaseHas('activities', [            'id' => $activity->id,            'title' => 'Atividade Atualizada',            'status' => 'completed',        ]);    }    /**     * Teste: atualizar atividade inexistente retorna 404.     */    public function test_update_activity_not_found(): void    {        $response = $this->put('/api/v1/activities/99999', [            'title' => 'Novo Título',        ]);        $response->assertStatus(404);        $response->assertJson([            'success' => false,            'status' => 404,        ]);    }    /**     * Teste: excluir atividade com sucesso (destroy).     */    public function test_destroy_activity_success(): void    {        $activity = $this->createActivity([            'activity_type_id' => $this->activityType->id,            'company_id' => $this->company->id,            'title' => 'Atividade para Excluir',            'status' => 'pending',        ]);        $response = $this->delete("/api/v1/activities/{$activity->id}");        $response->assertStatus(200);        $response->assertJson([            'success' => true,            'message' => 'Atividade removida com sucesso.',        ]);        $this->assertSoftDeleted('activities', [            'id' => $activity->id,        ]);    }    /**     * Teste: excluir atividade inexistente retorna 404.     */    public function test_destroy_activity_not_found(): void    {        $response = $this->delete('/api/v1/activities/99999');        $response->assertStatus(404);        $response->assertJson([            'success' => false,            'status' => 404,        ]);    }    /**     * Teste: rota sem autenticação retorna 401.     */    public function test_unauthenticated_request_returns_401(): void    {                $this->app['auth']->forgetGuards();

        $response = $this->get('/api/v1/activities');        $response->assertStatus(401);    }}